#include <stdio.h>

typedef struct {
    double x, y;
} Point;

int main(void) {
    Point p1, p2, p;

    if (scanf("%lf %lf %lf %lf %lf %lf",
              &p1.x, &p1.y, &p2.x, &p2.y, &p.x, &p.y) != 6) {
        return 0;
    }

    double vx = p2.x - p1.x;
    double vy = p2.y - p1.y;
    double wx = p.x - p1.x;
    double wy = p.y - p1.y;

    double t = (wx * vx + wy * vy) / (vx * vx + vy * vy);

    Point proj;
    proj.x = p1.x + t * vx;
    proj.y = p1.y + t * vy;

    printf("%.10f %.10f\n", proj.x, proj.y);
    return 0;
}

