#include <iostream>
#include <iomanip>
#include <cmath>

using namespace std;

int main() {
    double x1, y1, x2, y2, xp, yp;
    cin >> x1 >> y1 >> x2 >> y2 >> xp >> yp;

    // Vector from p1 to p2
    double dx = x2 - x1;
    double dy = y2 - y1;

    // Vector from p1 to p
    double vx = xp - x1;
    double vy = yp - y1;

    // Projection scalar t = (v · d) / (d · d)
    double t = (vx * dx + vy * dy) / (dx * dx + dy * dy);

    // Projection point coordinates
    double x = x1 + t * dx;
    double y = y1 + t * dy;

    // Output with sufficient precision
    cout << fixed << setprecision(10) << x << " " << y << endl;

    return 0;
}

