import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        double x1 = fs.nextDouble();
        double y1 = fs.nextDouble();
        double x2 = fs.nextDouble();
        double y2 = fs.nextDouble();
        double xp = fs.nextDouble();
        double yp = fs.nextDouble();

        double vx = x2 - x1;
        double vy = y2 - y1;

        double wx = xp - x1;
        double wy = yp - y1;

        double t = (wx * vx + wy * vy) / (vx * vx + vy * vy);

        double projX = x1 + t * vx;
        double projY = y1 + t * vy;

        System.out.printf(Locale.US, "%.10f %.10f%n", projX, projY);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            double val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = read();
            }

            if (c == '.') {
                double mul = 0.1;
                c = read();
                while (c >= '0' && c <= '9') {
                    val += (c - '0') * mul;
                    mul *= 0.1;
                    c = read();
                }
            }

            return val * sign;
        }
    }
}
